import java.io.*;

public class Guardar {
    public static void main(String[] args) {
        Persona p = new Persona("Ana", 22);
        try (ObjectOutputStream out =                // ✅ ERROR ② corregido: try-with-resources
                new ObjectOutputStream(new FileOutputStream("p.dat"))) {
            out.writeObject(p);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

class Persona implements Serializable {            // ✅ ERROR ① corregido: implements Serializable
    private static final long serialVersionUID = 1L;
    private String nombre;
    private int edad;

    Persona(String nombre, int edad) {
        this.nombre = nombre;
        this.edad = edad;
