public class Seleccion {
    public static void ordenar(int[] a) {
        for (int i = 0; i < a.length - 1; i++) {
            int min = i;
            for (int j = i + 1; j < a.length; j++) {
                if (a[j] < a[min]) {
                    min = j;
                }
            }
            int aux = a[i]; a[i] = a[min]; a[min] = aux;
        }
    }
    public static void main(String[] args) {
        int[] a = {29, 10, 14, 37, 13};
        ordenar(a);
